from hcso_tool.mock.export import encrypt, store_local_open, KS_NAME
from hcso_tool.utils.test import TestBase
from hcso_tool.models.params_constant import HCSO_SOC_PRIMARY_KS


class TestMock(TestBase):
    def test_scc(self):
        KS_NAME["SOC"] = HCSO_SOC_PRIMARY_KS
        self.expect(encrypt("soc", "a") == encrypt("soc", "a"), False)
        store_local_open()
        self.expect(encrypt("soc", "a"), encrypt("soc", "a"))


if __name__ == "__main__":
    TestMock().run()
